-- Fakt kartochkalari orqa tomonining ruscha matni — 65-partiya:
-- Fayzulla Xo'jayev, Furqat, Gulxaniy.

UPDATE fact_cards SET detail_ru = 'Файзулла Ходжаев родился 1 июля 1896 года в Бухаре, в семье крупного купца. От отца ему досталось в наследство большое богатство. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2178;
UPDATE fact_cards SET detail_ru = 'Окончив школу старого образца, он учился в бухарском медресе. В 1907–1912 годах он получал образование в Москве. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2179;
UPDATE fact_cards SET detail_ru = 'С 1913 года он деятельно участвовал в рядах джадидов и распространял просвещение в народе. Большое богатство, доставшееся от отца, он тратил на открытие школ нового метода. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2180;
UPDATE fact_cards SET detail_ru = 'Он работал в партии младобухарцев. С 1917 года вместе с Фитратом он возглавлял левое крыло партии. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2181;
UPDATE fact_cards SET detail_ru = 'После того как бухарский эмир был свергнут с престола, он был избран главой правительства. В 1922 году он ездил в Германию заключать договоры с зарубежными торговыми компаниями и крупными купцами. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2182;
UPDATE fact_cards SET detail_ru = 'В 1925 году он был избран председателем Совета народных комиссаров Узбекистана и возглавлял правительство до своего ареста в 1937 году. Как глава правительства он старался наладить связи с Ираном, Турцией, Афганистаном, Китаем, Азербайджаном, Германией и Японией. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2183;
UPDATE fact_cards SET detail_ru = 'Известны его книга «Материалы к истории бухарской революции» (1926) и статьи «Хозяйственное положение в БНСР» (1924), «Джадиды» (1926), «Басмачество» (1930). В 1932 году вышло его сочинение «К истории революции в Бухаре и национального размежевания Средней Азии». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2184;
UPDATE fact_cards SET detail_ru = 'Он был арестован 9 июля 1937 года в Москве и безосновательно обвинён в участии в деятельности «правотроцкистского блока». Приговор был приведён в исполнение на Бутовском полигоне под Москвой. 6 марта 1965 года Верховный суд СССР признал его невиновным и оправдал. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2185;

UPDATE fact_cards SET detail_ru = 'Фуркат родился в 1859 году в Коканде; настоящее его имя — Закирджан, сын Муллы Холмухаммада. Стихи он подписывал псевдонимом «Фуркат» и прославился под этим именем. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1926;
UPDATE fact_cards SET detail_ru = 'Фуркат сперва выучился грамоте в махаллинской школе, изучил арабский язык и каллиграфию. Затем, в 1873–1876 годах, он учился в медресе. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1927;
UPDATE fact_cards SET detail_ru = 'Фуркат глубоко изучил творчество Алишера Навои и наследие представителей персидской словесности и в совершенстве овладел персидским языком. Он сложил прекрасные назиры и тахмисы на сочинения Алишера Навои. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1928;
UPDATE fact_cards SET detail_ru = 'В 1876 году Фуркат по просьбе своего дяди-купца поехал в Новый Маргилан и помогал в торговых делах. Именно там он вполне сложился как сочинитель и, подписывая газели псевдонимом «Фуркат», начал приобретать известность. В начале 1880-х годов он вернулся в Коканд и создал семью, а в 1886–1887 годах жил в Маргилане в келье при мечети и открыл небольшую лавку. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1929;
UPDATE fact_cards SET detail_ru = 'В июне 1889 года Фуркат приехал в Ташкент и работал в «Туркистон вилоятининг газети». Он постоянно печатал в газете свои статьи. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1930;
UPDATE fact_cards SET detail_ru = 'В таких статьях, как «Польза знания», «Гимназия», «О выставке», «Суворов», Фуркат предстал проповедником новизны и развития, науки и европейского образования и культуры. Эти статьи печатались в 1890-е годы в «Туркистон вилоятининг газети». Потому он и считается одним из основоположников узбекской публицистики. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1931;
UPDATE fact_cards SET detail_ru = 'Фуркат — автор трактата «Хаммоми хаёл» и сочинения «Хаджнаме». Он перевёл с персидского повесть «Четыре дервиша» и создал стихотворную книгу «Нух манзар». Есть у него и сочинения «О положении поэта и о преувеличении в стихе» и «Путевые записки». Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1932;
UPDATE fact_cards SET detail_ru = '«Отпусти свою добычу, ловчий» — известный мусаддас Фурката. В нём поэт защищает право личности жить свободно и решительно обличает гнёт и произвол. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1933;
UPDATE fact_cards SET detail_ru = 'В июле 1891 года Фуркат отправился через Мерв, Ашхабад, Баку и Батуми в Стамбул, а оттуда прошёл и в Болгарию и Грецию. В 1892 году он посетил Мекку, Джидду и Медину, затем побывал в Бомбее и в Индии. А в марте 1893 года через Кашмир и Тибет перешёл в Восточный Туркестан. В Кашмире он написал стихотворение со строкой о том, что увидел лунноликую в краю Кашмира. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1934;
UPDATE fact_cards SET detail_ru = 'С 1893 года Фуркат постоянно жил в городе Яркенде в Восточном Туркестане. Сведущий во врачевании поэт открыл лавку по торговле лекарственными растениями, занимался творчеством и каллиграфией. В 1905 году он написал фельетон «Индийский фокусник в Яркенде». Умер он в 1909 году в Яркенде и погребён на яркендском кладбище Донгдор. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1935;

UPDATE fact_cards SET detail_ru = 'Предполагается, что Гульхани родился примерно в конце XVIII века в Коканде. Настоящее его имя — Мухаммад Шариф, а Гульхани — псевдоним. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1991;
UPDATE fact_cards SET detail_ru = 'Гульхани жил в Намангане и Коканде и некоторое время работал истопником в бане — гулахом. Псевдоним «Гульхани» и связан с этим занятием. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1992;
UPDATE fact_cards SET detail_ru = 'В 1801–1810 годах Гульхани состоял на службе в рядах нукеров кокандского хана Амира Алим-хана. После смерти Алим-хана Амир Умар-хан (Амири) привлёк его в круг придворных поэтов. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1993;
UPDATE fact_cards SET detail_ru = '«Зарбулмасал» считается редким образцом узбекской классической и всей восточной словесности. Гульхани с большой пользой употребил в нём около четырёхсот народных пословиц, садж (рифмованную прозу), басни и предания. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1994;
UPDATE fact_cards SET detail_ru = 'В сочинении приключения сватовства Ушастой Совы и Филина изображены иносказательно, в виде острой сатиры, и Гульхани через отношения птиц создал обличительную картину общественной жизни своего времени. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1995;
UPDATE fact_cards SET detail_ru = 'Гульхани творил на узбекском и таджикском языках; от него сохранилось несколько газелей и сатирических стихов. В таких стихах, как «Мой палец», «Грудь моя, как сердцевина тюльпана», отражены весна и картины действительной жизни. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1996;
UPDATE fact_cards SET detail_ru = 'Отдельные сведения о Гульхани приведены в тазкире Фазли Наманганийского «Маджмуаи шоирон» и Кари Рахматуллы Возеха «Тухфат уль-ахбоб». Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1997;
UPDATE fact_cards SET detail_ru = 'Точная дата смерти Гульхани неизвестна; в источниках указывается, что он умер примерно в 20-е годы XIX века. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1998;
